import React, { useState, useEffect, useRef } from 'react';
import { SendIcon, MicIcon } from './Icons';
import { speakText, stopSpeaking } from '../utils/speechSynthesis';

export const ChatPanel = ({
  companion,
  messages,
  onSendMessage,
  startListening,
  stopListening,
  isListening,
  onStopAI,
}) => {
  const [newMessage, setNewMessage] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [currentAudio, setCurrentAudio] = useState(null);
  const chatEndRef = useRef(null);

  // Auto scroll to latest message
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => {
      if (currentAudio) {
        currentAudio.pause();
        currentAudio.src = '';
      }
      stopSpeaking();
    };
  }, [currentAudio]);

  // Play message audio
  const handlePlayMessage = (message) => {
    handleStopAudio();

    if (message.audioUrl) {
      const audio = new Audio(message.audioUrl);
      setCurrentAudio(audio);
      
      audio.play().catch(err => {
        console.error('Audio playback failed:', err);
        speakText(message.text || message.content);
      });

      audio.onended = () => {
        setIsSpeaking(false);
        setCurrentAudio(null);
      };

      setIsSpeaking(true);
    } else if (message.text || message.content) {
      speakText(message.text || message.content);
      setIsSpeaking(true);

      const words = (message.text || message.content).split(' ').length;
      const duration = (words / 150) * 60 * 1000;
      setTimeout(() => setIsSpeaking(false), duration);
    }
  };

  const handleStopAudio = () => {
    stopSpeaking();
    
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
      setCurrentAudio(null);
    }
    
    setIsSpeaking(false);
  };

  // Send message handler
  const handleSubmit = (e) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    
    onSendMessage(newMessage);
    setNewMessage('');
  };

  const handleVoiceClick = () => {
    if (isListening) {
      stopListening();
    } else {
      startListening();
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-900">
      {/* Header */}
      <div className="p-4 border-b border-gray-700 flex items-center justify-between">
        <h3 className="text-lg font-semibold text-white">
          Chat with {companion?.name || 'AI Tutor'}
        </h3>

        <button
          onClick={onStopAI}
          className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white text-sm rounded-lg transition-colors"
        >
          Stop AI
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-400">
            <div className="text-6xl mb-4">🎓</div>
            <p>Start a conversation!</p>
          </div>
        ) : (
          messages.map((msg, idx) => (
            <div
              key={idx}
              className={`flex ${
                msg.sender === 'user' ? 'justify-end' : 'justify-start'
              }`}
            >
              <div
                className={`max-w-[75%] rounded-2xl px-4 py-2 ${
                  msg.sender === 'user'
                    ? 'bg-blue-600 text-white rounded-br-none'
                    : 'bg-gray-700 text-gray-100 rounded-bl-none'
                }`}
              >
                {/* User ID label for multi-user */}
                {msg.userId && msg.sender === 'user' && (
                  <p className="text-xs opacity-70 mb-1">
                    {msg.userId.substring(0, 12)}...
                  </p>
                )}

                <p className="text-sm whitespace-pre-wrap">
                  {msg.text}
                </p>

                {/* Play button - AI messages only */}
                {msg.sender !== 'user' && (
                  <button
                    onClick={() =>
                      isSpeaking ? handleStopAudio() : handlePlayMessage(msg)
                    }
                    className="mt-2 text-xs text-blue-300 hover:underline flex items-center gap-1"
                  >
                    {isSpeaking ? '⏸ Stop' : '▶ Play'}
                  </button>
                )}

                {msg.timestamp && (
                  <p className="text-xs opacity-70 mt-1">
                    {new Date(msg.timestamp).toLocaleTimeString([], {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </p>
                )}
              </div>
            </div>
          ))
        )}

        <div ref={chatEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-gray-700">
        <form onSubmit={handleSubmit} className="flex items-center gap-2">
          {/* Mic Button */}
          <button
            type="button"
            onClick={handleVoiceClick}
            className={`p-3 rounded-full transition-colors ${
              isListening
                ? 'bg-blue-600 animate-pulse'
                : 'bg-gray-700 hover:bg-gray-600'
            }`}
          >
            <MicIcon className="w-5 h-5 text-white" />
          </button>

          {/* Text Input */}
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type your message..."
            className="flex-1 bg-gray-800 text-white rounded-full px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />

          {/* Send Button */}
          <button
            type="submit"
            disabled={!newMessage.trim()}
            className="p-3 bg-blue-600 rounded-full disabled:bg-gray-700 disabled:cursor-not-allowed hover:bg-blue-700 transition-colors"
          >
            <SendIcon className="w-5 h-5 text-white" />
          </button>
        </form>

        {isListening && (
          <p className="mt-2 text-center text-blue-400 animate-pulse">
            🎤 Listening...
          </p>
        )}
      </div>
    </div>
  );
};
